import React, { useState, useMemo, useContext } from "react";

import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";

import { useCart } from "react-use-cart";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";

import { apivalue } from "../Data/AllData";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORIES
   ============================================================ */

const CATEGORIES = [
  {
    id: "All",
    label: "All",
    icon: Gem,
  },
  {
    id: "Rings",
    label: "Rings",
    icon: CircleDot,
  },
  {
    id: "Necklaces",
    label: "Necklaces",
    icon: Sparkles,
  },
  {
    id: "Bracelets",
    label: "Bracelets",
    icon: CircleDot,
  },
  {
    id: "Earrings",
    label: "Earrings",
    icon: Star,
  },
  {
    id: "Chains",
    label: "Chains",
    icon: Link2,
  },
  {
    id: "Watches",
    label: "Watches",
    icon: Watch,
  },
];

/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {
  const { addItem } = useCart();

  const Icon = product.icon || Gem;

  const [imgFailed, setImgFailed] = useState(false);

  const showImage = product.image && !imgFailed;

  const handleAddToCart = () => {
    addItem({
      id: product.id,
      title: product.name,
      price: Number(product.price),
      images: product.image ? [product.image] : [],
    });

    alert("Product added to cart successfully!");
  };

  return (
    <article className="lux-card">
      <div className="lux-card-media">

        {/* PRODUCT IMAGE */}

        {showImage ? (
          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-image-link"
          >
            <img
              src={product.image}
              alt={product.name}
              className="lux-card-img"
              loading="lazy"
              onError={() => setImgFailed(true)}
            />
          </Link>
        ) : (
          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-media-icon"
          >
            <Icon
              size={40}
              strokeWidth={1}
            />
          </Link>
        )}

        {/* BADGE */}

        {product.badge && (
          <span className="lux-card-badge">
            {product.badge}
          </span>
        )}

        {/* QUICK ADD */}

        <button
          type="button"
          className="lux-card-quickadd"
          aria-label={`Add ${product.name} to cart`}
          onClick={handleAddToCart}
        >
          <ShoppingBag
            size={16}
            strokeWidth={1.5}
          />
        </button>
      </div>

      {/* CARD BODY */}

      <div className="lux-card-body">

        <span className="lux-card-eyebrow">
          {product.category}
        </span>

        <h3 className="lux-card-name">
          {product.name}
        </h3>

        <div className="lux-card-price">
          ${Number(product.price).toFixed(2)}
        </div>

        <div className="lux-card-actions">

          {/* VIEW DETAILS */}

          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-btn lux-btn-outline"
          >
            View Details
          </Link>

          {/* ADD TO CART */}

          <button
            type="button"
            className="lux-btn lux-btn-solid"
            onClick={handleAddToCart}
          >
            Add to Cart
          </button>

        </div>
      </div>
    </article>
  );
}

