/* ============================================================
   ALL CART
   ============================================================ */

function AllCart() {

  const [selectedCategory, setSelectedCategory] =
    useState("All");

  /*
    نفس الـproducts الموجودة في AllData
    ومفيش PRODUCTS جديد هنا.
  */

  const products = useContext(apivalue);

  /*
    التأكد إن البيانات Array قبل استخدام map/filter
  */

  const filteredProducts = useMemo(() => {

    if (!Array.isArray(products)) {
      return [];
    }

    /*
      لو All:
      نستخدم نفس الـarray كما هي
    */

    if (selectedCategory === "All") {
      return products;
    }

    /*
      لو Category معينة:
      نفلتر نفس الـarray الموجودة في Context
    */

    return products.filter(
      (product) =>
        product.category === selectedCategory
    );

  }, [products, selectedCategory]);

  return (
    <>
      <style>{fontImport}</style>

      <main className="lux-page">

        {/* ====================================================
            HERO
        ==================================================== */}

        <section className="lux-collections-hero">

          <div className="lux-collections-hero-content">

            <span className="lux-hero-eyebrow">
              MAISON &amp; LUXE
            </span>

            <h1>
              Our Collections
            </h1>

            <p>
              Discover timeless pieces crafted to complement
              every moment and every story.
            </p>

          </div>

        </section>

        {/* ====================================================
            CATEGORIES
        ==================================================== */}

        <section className="lux-category-section">

          <div className="lux-category-list">

            {CATEGORIES.map((category) => {

              const Icon = category.icon;

              const isActive =
                selectedCategory === category.id;

              return (
                <button
                  key={category.id}
                  type="button"
                  className={
                    isActive
                      ? "lux-category-btn active"
                      : "lux-category-btn"
                  }
                  onClick={() =>
                    setSelectedCategory(category.id)
                  }
                >

                  <Icon
                    size={18}
                    strokeWidth={1.4}
                  />

                  <span>
                    {category.label}
                  </span>

                </button>
              );
            })}

          </div>

        </section>

        {/* ====================================================
            PRODUCTS
        ==================================================== */}

        <section className="lux-products-section">

          <div className="lux-products-header">

            <div>

              <span className="lux-products-eyebrow">
                COLLECTION
              </span>

              <h2>
                {selectedCategory === "All"
                  ? "All Pieces"
                  : selectedCategory}
              </h2>

            </div>

            <span className="lux-products-count">

              {filteredProducts.length}{" "}

              {filteredProducts.length === 1
                ? "piece"
                : "pieces"}

            </span>

          </div>

          {filteredProducts.length > 0 ? (

            <div className="lux-products-grid">

              {filteredProducts.map((product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              ))}

            </div>

          ) : (

            <div className="lux-empty-products">

              <Sparkles
                size={42}
                strokeWidth={1}
              />

              <h3>
                No products found
              </h3>

              <p>
                There are currently no products in this
                collection.
              </p>

              <button
                type="button"
                className="lux-btn lux-btn-solid"
                onClick={() =>
                  setSelectedCategory("All")
                }
              >
                View All Products
              </button>

            </div>

          )}

        </section>

        {/* ====================================================
            FOOTER
        ==================================================== */}

        <PlaceholderFooter />

      </main>
    </>
  );
}

/* ============================================================
   EXPORT
   ============================================================ */

export default AllCart;
